{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { Evaluator, formatValue } from './eval.js'
import { colIndex, addrKey } from './addr.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const line = lines[i].replace(/^[ \t]+/, '')
  if (line === '' || line[0] === '#') continue
  const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
  const raw = m[1]
  const content = m[2]
  const am = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(raw)
  if (!am || Number(am[2]) < 1) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${raw}\n`)
    process.exit(2)
  }
  const col = am[1].toUpperCase()
  const row = Number(am[2])
  const key = col + row
  if (cells.has(key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${key} is declared twice\n`)
    process.exit(2)
  }
  cells.set(key, { key, col, row, ci: colIndex(col), content })
}

const sorted = [...cells.values()].sort((a, b) => a.ci - b.ci || a.row - b.row)
for (const c of sorted) {
  c.ast = c.content[0] === '=' ? parseFormula(c.content.slice(1)) : null
}

const out = []
if (mode === 'values') {
  const ev = new Evaluator(cells)
  for (const c of sorted) out.push(`${c.key}=${formatValue(ev.cellValue(c.key))}`)
} else {
  for (const c of sorted) {
    const deps = new Map()
    if (c.ast) collect(c.ast, deps)
    const list = [...deps.values()].sort((a, b) => a.ci - b.ci || a.row - b.row)
    out.push(`${c.key}:` + list.map((d) => ' ' + d.key).join(''))
  }
}
process.stdout.write(out.length ? out.join('\n') + '\n' : '')

function collect(n, deps) {
  switch (n.type) {
    case 'ref': {
      const a = addrKey(n.name)
      if (a) deps.set(a.key, a)
      break
    }
    case 'range': {
      const a = addrKey(n.from)
      const b = addrKey(n.to)
      if (!a || !b) break
      for (let ci = Math.min(a.ci, b.ci); ci <= Math.max(a.ci, b.ci); ci++) {
        for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
          const k = addrKey(ci, r)
          deps.set(k.key, k)
        }
      }
      break
    }
    case 'call':
      n.args.forEach((x) => collect(x, deps))
      break
    case 'bin':
      collect(n.l, deps)
      collect(n.r, deps)
      break
    case 'un':
      collect(n.e, deps)
      break
  }
}
