{"file_path":"src/addr.js","content":"export function colIndex(col) {
  if (col.length === 1) return col.charCodeAt(0) - 64
  return 26 + (col.charCodeAt(0) - 65) * 26 + (col.charCodeAt(1) - 64)
}

export function colName(ci) {
  if (ci <= 26) return String.fromCharCode(64 + ci)
  const k = ci - 26 - 1
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}

// addrKey(word) parses an address word; addrKey(ci, row) builds one.
// Returns null when the word is not an addressable cell.
export function addrKey(a, b) {
  if (typeof a === 'number') {
    return { ci: a, row: b, key: colName(a) + b }
  }
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(a)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const col = m[1].toUpperCase()
  return { ci: colIndex(col), row, key: col + row }
}
"}

{"file_path":"src/parse.js","content":"// Returns an AST, or null when the grammar rejects the body.
export function parseFormula(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(src.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  let p = 0
  const fail = new Error('parse')
  const peekOp = () => (toks[p] && toks[p].k === 'op' ? toks[p].v : null)

  function cmp() {
    let l = add()
    while (['=', '<>', '<', '<=', '>', '>='].includes(peekOp())) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp() === '+' || peekOp() === '-') {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp() === '*' || peekOp() === '/') {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp() === '^') {
      p++
      return { type: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (peekOp() === '-' || peekOp() === '+') {
      const op = toks[p++].v
      return { type: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw fail
    if (t.k === 'num') { p++; return { type: 'num', v: t.v } }
    if (t.k === 'op') {
      if (t.v !== '(') throw fail
      p++
      const e = cmp()
      if (peekOp() !== ')') throw fail
      p++
      return e
    }
    p++
    const name = t.v
    if (peekOp() === '(') {
      p++
      const args = []
      if (peekOp() === ')') { p++ } else {
        for (;;) {
          args.push(cmp())
          if (peekOp() === ',') { p++; continue }
          if (peekOp() === ')') { p++; break }
          throw fail
        }
      }
      return { type: 'call', name: name.toUpperCase(), args }
    }
    const up = name.toUpperCase()
    if (up === 'TRUE' || up === 'FALSE') return { type: 'bool', v: up === 'TRUE' }
    if (peekOp() === ':') {
      p++
      const t2 = toks[p]
      if (!t2 || t2.k !== 'word') throw fail
      p++
      return { type: 'range', from: name, to: t2.v }
    }
    return { type: 'ref', name }
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === fail) return null
    throw e
  }
}
"}

