{"file_path":"src/addr.js","content":"export function colIndex(col) {
  if (col.length === 1) return col.charCodeAt(0) - 64
  return 26 + (col.charCodeAt(0) - 65) * 26 + (col.charCodeAt(1) - 64)
}

export function colName(ci) {
  if (ci <= 26) return String.fromCharCode(64 + ci)
  const k = ci - 26 - 1
  return String.fromCharCode(65 + Math.floor(k / 26)) + String.fromCharCode(65 + (k % 26))
}

// addrKey(word) parses an address word; addrKey(ci, row) builds one.
// Returns null when the word is not an addressable cell.
export function addrKey(a, b) {
  if (typeof a === 'number') {
    return { ci: a, row: b, key: colName(a) + b }
  }
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(a)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const col = m[1].toUpperCase()
  return { ci: colIndex(col), row, key: col + row }
}
"}

{"file_path":"src/parse.js","content":"// Returns an AST, or null when the grammar rejects the body.
export function parseFormula(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(src.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  let p = 0
  const fail = new Error('parse')
  const peekOp = () => (toks[p] && toks[p].k === 'op' ? toks[p].v : null)

  function cmp() {
    let l = add()
    while (['=', '<>', '<', '<=', '>', '>='].includes(peekOp())) {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (peekOp() === '+' || peekOp() === '-') {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (peekOp() === '*' || peekOp() === '/') {
      const op = toks[p++].v
      l = { type: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (peekOp() === '^') {
      p++
      return { type: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (peekOp() === '-' || peekOp() === '+') {
      const op = toks[p++].v
      return { type: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = toks[p]
    if (!t) throw fail
    if (t.k === 'num') { p++; return { type: 'num', v: t.v } }
    if (t.k === 'op') {
      if (t.v !== '(') throw fail
      p++
      const e = cmp()
      if (peekOp() !== ')') throw fail
      p++
      return e
    }
    p++
    const name = t.v
    if (peekOp() === '(') {
      p++
      const args = []
      if (peekOp() === ')') { p++ } else {
        for (;;) {
          args.push(cmp())
          if (peekOp() === ',') { p++; continue }
          if (peekOp() === ')') { p++; break }
          throw fail
        }
      }
      return { type: 'call', name: name.toUpperCase(), args }
    }
    const up = name.toUpperCase()
    if (up === 'TRUE' || up === 'FALSE') return { type: 'bool', v: up === 'TRUE' }
    if (peekOp() === ':') {
      p++
      const t2 = toks[p]
      if (!t2 || t2.k !== 'word') throw fail
      p++
      return { type: 'range', from: name, to: t2.v }
    }
    return { type: 'ref', name }
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === fail) return null
    throw e
  }
}
"}

{"file_path":"src/eval.js","content":"import { addrKey } from './addr.js'

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const num = (v) => ({ t: 'n', v })
const err = (v) => ({ t: 'e', v })
const ZERO = num(0)

export function formatValue(v) {
  switch (v.t) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

const rank = { n: 0, s: 1, b: 2 }
function compareCP(a, b) {
  const x = Array.from(a)
  const y = Array.from(b)
  for (let i = 0; i < x.length && i < y.length; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}
function compare(a, b) {
  if (a.t !== b.t) return rank[a.t] < rank[b.t] ? -1 : 1
  if (a.t === 's') return compareCP(a.v, b.v)
  const x = Number(a.v)
  const y = Number(b.v)
  return x < y ? -1 : x > y ? 1 : 0
}

function toNum(v) {
  if (v.t === 'n') return v
  if (v.t === 'b') return num(v.v ? 1 : 0)
  if (v.t === 's') return err('#VALUE!')
  return v
}
const finite = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))

export class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.memo = new Map()
    this.stack = new Set()
  }

  cellValue(key) {
    if (this.memo.has(key)) return this.memo.get(key)
    const c = this.cells.get(key)
    if (!c) return ZERO
    if (this.stack.has(key)) return err('#CYCLE!')
    this.stack.add(key)
    let v
    if (c.content[0] === '=') {
      v = c.ast ? this.ev(c.ast) : err('#ERR!')
    } else if (c.content === '') v = ZERO
    else if (/^-?[0-9]+(\.[0-9]+)?$/.test(c.content)) v = num(Number(c.content))
    else if (ERRS.includes(c.content)) v = err(c.content)
    else v = { t: 's', v: c.content }
    this.stack.delete(key)
    this.memo.set(key, v)
    return v
  }

  ref(name) {
    const a = addrKey(name)
    return a ? this.cellValue(a.key) : err('#REF!')
  }

  rangeValues(n) {
    const a = addrKey(n.from)
    const b = addrKey(n.to)
    if (!a || !b) return [err('#REF!')]
    const out = []
    for (let ci = Math.min(a.ci, b.ci); ci <= Math.max(a.ci, b.ci); ci++) {
      for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) {
        out.push(this.cellValue(addrKey(ci, r).key))
      }
    }
    return out
  }

  ev(n) {
    switch (n.type) {
      case 'num': return num(n.v)
      case 'bool': return { t: 'b', v: n.v }
      case 'ref': return this.ref(n.name)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = toNum(this.ev(n.e))
        if (v.t === 'e') return v
        return num(n.op === '-' ? -v.v : v.v)
      }
      case 'bin': return this.bin(n)
      case 'call': return this.call(n)
    }
  }

  bin(n) {
    const l = this.ev(n.l)
    if (l.t === 'e') return l
    const r = this.ev(n.r)
    if (r.t === 'e') return r
    if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
      const c = compare(l, r)
      const res = { '=': c === 0, '<>': c !== 0, '<': c < 0, '<=': c <= 0, '>': c > 0, '>=': c >= 0 }[n.op]
      return { t: 'b', v: res }
    }
    const a = toNum(l)
    if (a.t === 'e') return a
    const b = toNum(r)
    if (b.t === 'e') return b
    switch (n.op) {
      case '+': return finite(a.v + b.v)
      case '-': return finite(a.v - b.v)
      case '*': return finite(a.v * b.v)
      case '/': return b.v === 0 ? err('#DIV/0!') : finite(a.v / b.v)
      case '^': return finite(Math.pow(a.v, b.v))
    }
  }

  call(n) {
    const name = n.name
    const k = n.args.length
    if (name === 'IF') {
      if (k !== 3 || n.args.some((a) => a.type === 'range')) return err('#ERR!')
      const c = this.ev(n.args[0])
      if (c.t === 'e') return c
      let truth
      if (c.t === 'b') truth = c.v
      else if (c.t === 'n') truth = c.v !== 0
      else return err('#VALUE!')
      return this.ev(n.args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      if (k !== 1 || n.args[0].type === 'range') return err('#ERR!')
      const v = toNum(this.ev(n.args[0]))
      return v.t === 'e' ? v : num(Math.abs(v.v))
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (k < 1) return err('#ERR!')
    const vals = []
    for (const a of n.args) {
      if (a.type === 'range') vals.push(...this.rangeValues(a))
      else vals.push(this.ev(a))
    }
    const e = vals.find((v) => v.t === 'e')
    if (e) return e
    if (name === 'COUNT') return num(vals.filter((v) => v.t === 'n').length)
    const nums = []
    for (const v of vals) {
      const x = toNum(v)
      if (x.t === 'e') return x
      nums.push(x.v)
    }
    switch (name) {
      case 'SUM': return finite(nums.reduce((s, x) => s + x, 0))
      case 'MIN': return num(Math.min(...nums))
      case 'MAX': return num(Math.max(...nums))
      case 'AVG': return finite(nums.reduce((s, x) => s + x, 0) / nums.length)
    }
  }
}
"}

